import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import request from 'supertest';
import path from 'path';
import os from 'os';
import fs from 'fs';
import Database from 'better-sqlite3';
import { createApp } from '../src/app.js';

describe('M3 - Presença - Fatia 4 (Presença Manual e Limites)', () => {
  let app: any;
  let dbPath: string;

  beforeEach(async () => {
    const tmpDir = os.tmpdir();
    dbPath = path.join(tmpDir, `test-presenca-f4-${Date.now()}-${Math.random()}.sqlite`);
    app = createApp({ dbPath, modoTeste: true });
    await request(app).post('/_teste/reset');
  });

  afterEach(() => {
    app?.close?.();
    if (fs.existsSync(dbPath)) {
      try {
        fs.unlinkSync(dbPath);
      } catch {}
    }
  });

  it('critério 9 (R6) — tentativa de presença manual sem justificativa ou com menos de 10 caracteres deve retornar 422 JUSTIFICATIVA_OBRIGATORIA', async () => {
    const atividadeRes = await request(app)
      .post('/atividades')
      .set('X-Usuario', 'org-ana')
      .send({
        titulo: 'Palestra Manual',
        tipo: 'palestra',
        salaId: 'sala-101',
        vagas: 20,
        encontros: [
          { inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T11:00:00-03:00' }
        ]
      });

    const encontroId = atividadeRes.body.encontros[0].id;

    // Sem justificativa
    const resSem = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla'
      });

    expect(resSem.status).toBe(422);
    expect(resSem.body.erro).toBe('JUSTIFICATIVA_OBRIGATORIA');

    // Com justificativa curta (< 10 caracteres)
    const resCurta = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla',
        justificativa: 'Falta luz'
      });

    expect(resCurta.status).toBe(422);
    expect(resCurta.body.erro).toBe('JUSTIFICATIVA_OBRIGATORIA');
  });

  it('critério 10 (R7) — tentativa de presença manual fora do período permitido (antes da janela ou mais de 2h após o fim) deve retornar 422 FORA_DA_JANELA', async () => {
    const atividadeRes = await request(app)
      .post('/atividades')
      .set('X-Usuario', 'org-ana')
      .send({
        titulo: 'Palestra Janela Manual',
        tipo: 'palestra',
        salaId: 'sala-101',
        vagas: 20,
        encontros: [
          { inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T11:00:00-03:00' }
        ]
      });

    const atividadeId = atividadeRes.body.id;
    const encontroId = atividadeRes.body.encontros[0].id;

    const db = new Database(dbPath);
    db.prepare(`
      INSERT INTO inscricoes (id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run('ins-carla-f4', atividadeId, 'p-carla', 'confirmada', null, null, '2026-10-18T10:00:00-03:00');
    db.close();

    // Antes da janela (encontro 10:00, janela inicia 09:45. Testar em 09:44:00)
    await request(app)
      .put('/_teste/relogio')
      .send({ agora: '2026-10-19T09:44:00-03:00' });

    const resAntes = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla',
        justificativa: 'Participou presencialmente mas esqueceu cracha'
      });

    expect(resAntes.status).toBe(422);
    expect(resAntes.body.erro).toBe('FORA_DA_JANELA');

    // Depois de 2h do fim (fim 11:00, limite 13:00. Testar em 13:01:00)
    await request(app)
      .put('/_teste/relogio')
      .send({ agora: '2026-10-19T13:01:00-03:00' });

    const resDepois = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla',
        justificativa: 'Participou presencialmente mas esqueceu cracha'
      });

    expect(resDepois.status).toBe(422);
    expect(resDepois.body.erro).toBe('FORA_DA_JANELA');
  });

  it('critério 12 (R9) e R15 — presença manual para participante sem inscrição confirmada deve retornar 403 NAO_INSCRITO', async () => {
    const atividadeRes = await request(app)
      .post('/atividades')
      .set('X-Usuario', 'org-ana')
      .send({
        titulo: 'Palestra Nao Inscrito Manual',
        tipo: 'palestra',
        salaId: 'sala-101',
        vagas: 20,
        encontros: [
          { inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T11:00:00-03:00' }
        ]
      });

    const encontroId = atividadeRes.body.encontros[0].id;

    await request(app)
      .put('/_teste/relogio')
      .send({ agora: '2026-10-19T10:05:00-03:00' });

    const res = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla',
        justificativa: 'Participou presencialmente mas esqueceu cracha'
      });

    expect(res.status).toBe(403);
    expect(res.body.erro).toBe('NAO_INSCRITO');
  });

  it('critério 11 (R8) — tentativa de presença manual que excede o limite de 10% das inscrições confirmadas deve retornar 422 LIMITE_DE_MANUAIS', async () => {
    const atividadeRes = await request(app)
      .post('/atividades')
      .set('X-Usuario', 'org-ana')
      .send({
        titulo: 'Palestra Limite Manuais',
        tipo: 'palestra',
        salaId: 'sala-101',
        vagas: 20,
        encontros: [
          { inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T11:00:00-03:00' }
        ]
      });

    const atividadeId = atividadeRes.body.id;
    const encontroId = atividadeRes.body.encontros[0].id;

    // 5 confirmados -> 10% = 0.5 -> ceil = 1 manual permitida
    const db = new Database(dbPath);
    const participantes = ['p-carla', 'p-diego', 'p-elisa', 'p-fabio', 'p-gabriela'];
    participantes.forEach((pId, idx) => {
      db.prepare(`
        INSERT INTO inscricoes (id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(`ins-${idx}`, atividadeId, pId, 'confirmada', null, null, '2026-10-18T10:00:00-03:00');
    });
    db.close();

    await request(app)
      .put('/_teste/relogio')
      .send({ agora: '2026-10-19T10:05:00-03:00' });

    // Primeira presença manual (permitida)
    const res1 = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-carla',
        justificativa: 'Primeira justificativa valida'
      });

    expect(res1.status).toBe(201);

    // Segunda presença manual (excede limite de 1)
    const res2 = await request(app)
      .post(`/encontros/${encontroId}/presencas/manual`)
      .set('X-Usuario', 'org-ana')
      .send({
        participanteId: 'p-diego',
        justificativa: 'Segunda justificativa valida'
      });

    expect(res2.status).toBe(422);
    expect(res2.body.erro).toBe('LIMITE_DE_MANUAIS');
  });
});

import Database from 'better-sqlite3';

export interface PresencaRow {
  id: string;
  encontroId: string;
  participanteId: string;
  origem: string;
  lidoEm: string;
  registradaEm: string;
  justificativa: string | null;
}

export class PresencaRepository {
  constructor(private db: Database.Database) {}

  findByEncontroAndParticipante(encontroId: string, participanteId: string): PresencaRow | null {
    const row = this.db.prepare(`
      SELECT id, encontroId, participanteId, origem, lidoEm, registradaEm, justificativa
      FROM presencas
      WHERE encontroId = ? AND participanteId = ?
    `).get(encontroId, participanteId) as PresencaRow | undefined;

    return row || null;
  }

  create(presenca: PresencaRow): void {
    this.db.prepare(`
      INSERT INTO presencas (id, encontroId, participanteId, origem, lidoEm, registradaEm, justificativa)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run(
      presenca.id,
      presenca.encontroId,
      presenca.participanteId,
      presenca.origem,
      presenca.lidoEm,
      presenca.registradaEm,
      presenca.justificativa
    );
  }

  countManualByEncontro(encontroId: string): number {
    const row = this.db.prepare(`
      SELECT COUNT(*) as count FROM presencas
      WHERE encontroId = ? AND origem = 'manual'
    `).get(encontroId) as { count: number };
    return row.count;
  }
}

import Database from 'better-sqlite3';

export interface InscricaoData {
  id: string;
  atividadeId: string;
  participanteId: string;
  status: 'confirmada' | 'em_espera' | 'convocada' | 'cancelada' | 'expirada';
  posicaoNaEspera: number | null;
  convocadaAte: string | null;
  criadaEm: string;
}

export class InscricaoRepository {
  constructor(private db: Database.Database) {}

  findStatus(atividadeId: string, participanteId: string): string | null {
    const row = this.db.prepare(`
      SELECT status FROM inscricoes
      WHERE atividadeId = ? AND participanteId = ?
    `).get(atividadeId, participanteId) as { status: string } | undefined;

    return row ? row.status : null;
  }

  findByActivityAndParticipant(atividadeId: string, participanteId: string): InscricaoData | null {
    const row = this.db.prepare(`
      SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
      FROM inscricoes
      WHERE atividadeId = ? AND participanteId = ?
    `).get(atividadeId, participanteId) as InscricaoData | undefined;

    return row || null;
  }

  create(inscricao: InscricaoData): void {
    this.db.prepare(`
      INSERT INTO inscricoes (id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run(
      inscricao.id,
      inscricao.atividadeId,
      inscricao.participanteId,
      inscricao.status,
      inscricao.posicaoNaEspera,
      inscricao.convocadaAte,
      inscricao.criadaEm
    );
  }

  countOccupied(atividadeId: string): number {
    const row = this.db.prepare(`
      SELECT COUNT(*) as count FROM inscricoes
      WHERE atividadeId = ? AND status IN ('confirmada', 'convocada')
    `).get(atividadeId) as { count: number };
    return row.count;
  }

  countConfirmed(atividadeId: string): number {
    const row = this.db.prepare(`
      SELECT COUNT(*) as count FROM inscricoes
      WHERE atividadeId = ? AND status = 'confirmada'
    `).get(atividadeId) as { count: number };
    return row.count;
  }

  countInWaitlist(atividadeId: string): number {
    const row = this.db.prepare(`
      SELECT COUNT(*) as count FROM inscricoes
      WHERE atividadeId = ? AND status = 'em_espera'
    `).get(atividadeId) as { count: number };
    return row.count;
  }

  countOccupiedMinicursos(participanteId: string): number {
    const row = this.db.prepare(`
      SELECT COUNT(DISTINCT i.atividadeId) as count
      FROM inscricoes i
      JOIN atividades a ON a.id = i.atividadeId
      WHERE i.participanteId = ?
        AND i.status IN ('confirmada', 'convocada')
        AND a.tipo = 'minicurso'
        AND a.cancelada = 0
    `).get(participanteId) as { count: number };
    return row.count;
  }

  getOccupiedEncountersForParticipant(participanteId: string): Array<{ inicio: string; fim: string }> {
    return this.db.prepare(`
      SELECT e.inicio, e.fim
      FROM inscricoes i
      JOIN encontros e ON e.atividade_id = i.atividadeId
      JOIN atividades a ON a.id = i.atividadeId
      WHERE i.participanteId = ?
        AND i.status IN ('confirmada', 'convocada')
        AND a.cancelada = 0
    `).all(participanteId) as Array<{ inicio: string; fim: string }>;
  }

  findByParticipant(participanteId: string, atividadeId?: string): InscricaoData[] {
    if (atividadeId) {
      return this.db.prepare(`
        SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
        FROM inscricoes
        WHERE participanteId = ? AND atividadeId = ?
        ORDER BY criadaEm ASC
      `).all(participanteId, atividadeId) as InscricaoData[];
    }
    return this.db.prepare(`
      SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
      FROM inscricoes
      WHERE participanteId = ?
      ORDER BY criadaEm ASC
    `).all(participanteId) as InscricaoData[];
  }

  findAll(atividadeId?: string): InscricaoData[] {
    if (atividadeId) {
      return this.db.prepare(`
        SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
        FROM inscricoes
        WHERE atividadeId = ?
        ORDER BY criadaEm ASC
      `).all(atividadeId) as InscricaoData[];
    }
    return this.db.prepare(`
      SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
      FROM inscricoes
      ORDER BY criadaEm ASC
    `).all() as InscricaoData[];
  }

  findById(id: string): InscricaoData | null {
    const row = this.db.prepare(`
      SELECT id, atividadeId, participanteId, status, posicaoNaEspera, convocadaAte, criadaEm
      FROM inscricoes
      WHERE id = ?
    `).get(id) as InscricaoData | undefined;

    return row || null;
  }

  getEndedActivitiesForParticipant(participanteId: string): Array<{ atividadeId: string; maxFim: string }> {
    return this.db.prepare(`
      SELECT i.atividadeId, MAX(e.fim) as maxFim
      FROM inscricoes i
      JOIN encontros e ON e.atividade_id = i.atividadeId
      JOIN atividades a ON a.id = i.atividadeId
      WHERE i.participanteId = ?
        AND i.status IN ('confirmada', 'convocada')
        AND a.cancelada = 0
      GROUP BY i.atividadeId
    `).all(participanteId) as Array<{ atividadeId: string; maxFim: string }>;
  }

  hasPresencaInActivity(atividadeId: string, participanteId: string): boolean {
    const row = this.db.prepare(`
      SELECT p.id
      FROM presencas p
      JOIN encontros e ON e.id = p.encontroId
      WHERE e.atividade_id = ? AND p.participanteId = ?
      LIMIT 1
    `).get(atividadeId, participanteId);
    return !!row;
  }
}

import { ActivityRepository } from '../repositories/activity-repository.js';
import { InscricaoRepository } from '../repositories/inscricao-repository.js';
import { PresencaRepository, PresencaRow } from '../repositories/presenca-repository.js';
import { Clock } from '../clock/clock.js';
import { DomainError } from '../domain/activity.js';
import { NotFoundError } from './errors.js';
import { DateTime } from 'luxon';
import crypto from 'crypto';

export class RegisterPresencaManualUseCase {
  constructor(
    private activityRepository: ActivityRepository,
    private inscricaoRepository: InscricaoRepository,
    private presencaRepository: PresencaRepository,
    private clock: Clock
  ) {}

  execute(encontroId: string, participanteId: string, input: { participanteId?: string; justificativa?: string }): { presenca: PresencaRow; statusCode: number } {
    const result = this.activityRepository.findEncounterWithActivity(encontroId);
    if (!result) {
      throw new NotFoundError('Encontro não encontrado');
    }

    const justificativa = input.justificativa;
    if (!justificativa || typeof justificativa !== 'string' || justificativa.trim().length < 10) {
      throw new DomainError('JUSTIFICATIVA_OBRIGATORIA', 'Justificativa obrigatória com no mínimo 10 caracteres');
    }

    const existing = this.presencaRepository.findByEncontroAndParticipante(encontroId, participanteId);
    if (existing) {
      return { presenca: existing, statusCode: 200 };
    }

    const statusInscricao = this.inscricaoRepository.findStatus(result.activity.id, participanteId);
    if (statusInscricao !== 'confirmada') {
      throw new DomainError('NAO_INSCRITO', 'Participante sem inscrição confirmada');
    }

    const agora = this.clock.now();
    const inicio = DateTime.fromISO(result.encounter.inicio, { setZone: true });
    const fim = DateTime.fromISO(result.encounter.fim, { setZone: true });
    const janelaInicio = inicio.minus({ minutes: 15 });
    const limiteFim = fim.plus({ hours: 2 });

    if (agora < janelaInicio || agora > limiteFim) {
      throw new DomainError('FORA_DA_JANELA', 'Fora da janela de presença manual');
    }

    const confirmados = this.inscricaoRepository.countConfirmed(result.activity.id);
    const limiteManuais = Math.ceil(confirmados * 0.1);
    const manuaisAtuais = this.presencaRepository.countManualByEncontro(encontroId);
    if (manuaisAtuais >= limiteManuais) {
      throw new DomainError('LIMITE_DE_MANUAIS', 'Limite de presenças manuais atingido');
    }

    const id = 'pre_' + crypto.randomBytes(4).toString('hex');
    const presenca: PresencaRow = {
      id,
      encontroId,
      participanteId,
      origem: 'manual',
      lidoEm: agora.toISO()!,
      registradaEm: agora.toISO()!,
      justificativa
    };

    this.presencaRepository.create(presenca);

    return { presenca, statusCode: 201 };
  }
}
